/* LIAD shared storefront and academy. Product source: data/products.json. */
(() => {
'use strict';
const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => new Intl.NumberFormat('he-IL',{style:'currency',currency:'ILS',maximumFractionDigits:2,minimumFractionDigits:Number.isInteger(n)?0:2}).format(n);
const products = window.LIAD_PRODUCTS.products;
const courses = window.SYLLABI;
const articles = window.ARTICLES;
const params = new URLSearchParams(location.search);
const page = location.pathname.split('/').pop() || 'index.html';
const originalHome=document.body.classList.contains('original-home');
const MAIL = 'rubinliad@gmail.com';
const SHIPPING = {flat:29.9, freeFrom:329.9};
const PAY = Object.assign({cardEndpoint:'',bitLink:''}, window.LIAD_PAYMENT||{});
const categories = {'gel-polish':'לק ג׳ל','builder-gel':'ג׳ל בנייה','bases':'בייסים וטופים','polygel':'אקריג׳ל ופוליג׳ל','regular-polish':'לק רגיל','machines':'מכונות שיוף','lamps':'מנורות ייבוש','tools':'כלי עבודה','nail-art':'קישוטים ונייל ארט','hygiene':'חיטוי והיגיינה','starter-kits':'ערכות עבודה','disposable':'חד־פעמי','files':'פצירות ובאפרים'};
const courseInfo = {
 'gel-anatomy':{n:'01',audience:'למתחילות',fit:'למתעניינות שרוצות ללמוד ולהתמקצע היטב בעולם הציפורניים, ולרכוש מקצוע.',meetings:6,highlights:['מניקור נכון, נקי ומדויק','יצירת מבנה אנטומי','מריחת ג׳ל קרובה ומדויקת','זיהוי נקודת האפקס'],kit:'ערכת עבודה מלאה בשווי 2,000 ₪'},
 acrygel:{n:'02',audience:'למקצועיות',fit:'למקצועיות בתחום הלק ג׳ל שרוצות להתרחב ולהתמקצע בבנייה.',meetings:6,highlights:['בניית ציפורן מאקריג׳ל','בנייה בתבניות ובטיפס הפוך','שיטת שיוף נכונה','מילוי על מודליסטית'],kit:'ערכת עבודה מלאה, כולל ערכת אקריג׳ל'},
 teens:{n:'03',audience:'לנערות',fit:'לנערות שמתעניינות ורוצות להכיר היטב את עולם הציפורניים.',meetings:4,highlights:['אנטומיה של הציפורן','מניקור עדין ונכון','מריחת לק ג׳ל קרובה ומדויקת','שליטה בכלי העבודה'],kit:'ערכת עבודה, כולל מנורת ייבוש SUN'},
 pedicure:{n:'04',audience:'למתעניינות בפדיקור',fit:'למתעניינות בלימודי פדיקור מעמיק, בתחום טיפולי מקצועי ומבוקש.',meetings:6,highlights:['פדיקור קוסמטי פלוס','טיפול בסדקים וביבלות מסמר','פטרת ועיוותים בציפורן','מיגון עצמי ופרוטוקול עבודה'],kit:'ערכת עבודה גדולה בשווי 1,700 ₪'}
};
const iconPaths = {search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',bag:'<path d="M5 8h14l1 13H4L5 8Z"/><path d="M9 9V6a3 3 0 0 1 6 0v3"/>',heart:'<path d="M20 5a5 5 0 0 0-8 1 5 5 0 0 0-8-1c-5 5 8 15 8 15S25 10 20 5Z"/>',menu:'<path d="M4 7h16M4 16h16"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',arrow:'<path d="M19 12H5m7-7-7 7 7 7"/>'};
const icon = key => `<svg viewBox="0 0 24 24" aria-hidden="true">${iconPaths[key]}</svg>`;
const arrow = '';
const btn = (text,href,style='') => `<a class="btn ${style}" href="${esc(href)}">${esc(text)}${arrow}</a>`;
const image = (src,alt,extra='') => `<img src="${esc(src)}" alt="${esc(alt)}" ${extra}>`;
const crumb = (label, middle='') => `<nav class="crumb wrap" aria-label="פירורי לחם"><a href="index.html">בית</a><span aria-hidden="true">/</span>${middle}<span>${esc(label)}</span></nav>`;
const heading = (title,lead,kicker='LIAD STUDIO',cls='') => `<div class="page-heading ${cls}"><p class="eyebrow">${kicker}</p><h1>${title}</h1>${lead?`<p class="lead">${lead}</p>`:''}</div>`;
function read(key, fallback) {try {return JSON.parse(localStorage.getItem(key)) ?? fallback;} catch {return fallback;}}
function write(key,value) {try{localStorage.setItem(key,JSON.stringify(value));}catch{toast('הדפדפן לא מאפשר שמירה. הסל יישמר עד לסגירת הדף.');}}
let cart = read('liad:cart',[]);
cart = Array.isArray(cart) ? cart.filter(x => products.some(p => p.id === x.id) && Number.isFinite(+x.qty) && +x.qty>0).map(x=>({id:x.id,qty:Math.min(Math.floor(+x.qty),products.find(p=>p.id===x.id).stock)})).filter(x=>x.qty>0):[];
let favorites = read('liad:favorites',[]); favorites = Array.isArray(favorites) ? favorites.filter(id=>products.some(p=>p.id===id)):[];
let toastTimer;
function toast(message) {const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2800);}
function count(){return cart.reduce((n,l)=>n+l.qty,0);}
function subtotal(){return cart.reduce((n,l)=>n+products.find(p=>p.id===l.id).price*l.qty,0);}
function updateCart(){write('liad:cart',cart);updateDock();$$('[data-cart-count]').forEach(el=>el.textContent=count());renderCart();if(page==='checkout.html')renderCheckoutSummary();}
function add(id, qty=1, trigger=null, keyboard=false){const p=products.find(x=>x.id===id);if(!p)return;qty=Math.floor(Number(qty));if(!Number.isFinite(qty)||qty<1){toast('יש לבחור כמות של יחידה אחת לפחות.');return;}const item=cart.find(x=>x.id===id);if((item?.qty||0)+qty>p.stock){toast('הכמות המבוקשת גדולה מהמלאי שבקטלוג.');return;}if(item)item.qty+=qty;else cart.push({id,qty});updateCart();addFeedback(p,trigger,keyboard);toast('המוצר נוסף לסל שלך');}
function saveFavorite(id){favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];write('liad:favorites',favorites);$$('[data-favorite]').filter(el=>el.dataset.favorite===id).forEach(el=>{el.setAttribute('aria-pressed',String(favorites.includes(id)));el.setAttribute('aria-label',(favorites.includes(id)?'הסרה מהמועדפים: ':'שמירה במועדפים: ')+products.find(p=>p.id===id).title);});if(page==='shop.html'&&params.get('favorites')==='1')renderCatalog();}
// Keep short Latin runs (brand + line names) on one line inside Hebrew titles.
const latin=t=>t.replace(/[A-Za-z][A-Za-z0-9.+\- ]*[A-Za-z0-9]/g,m=>m.length<=22?`<bdi class="nw">${m}</bdi>`:m);
function productCard(p){const url=`product.html?id=${encodeURIComponent(p.id)}`,out=p.stock<=0,fav=favorites.includes(p.id);return `<article class="product-card${out?' is-out':''}"><div class="product-visual"><a class="product-media" href="${url}" tabindex="-1" aria-hidden="true">${image(p.image,'','loading="lazy" decoding="async"')}</a><button type="button" class="favorite" data-favorite="${esc(p.id)}" aria-pressed="${fav}" aria-label="${fav?'הסרה מהמועדפים':'שמירה במועדפים'}: ${esc(p.title)}">${icon('heart')}</button></div><div class="product-info"><span class="product-label" dir="ltr">${esc(p.brand)}</span><h3><a href="${url}">${latin(esc(p.title))}</a></h3><bdi class="price card-price">${money(p.price)}</bdi></div><div class="product-buy"><button type="button" class="add-small" data-add="${esc(p.id)}" ${out?'disabled':''}><span>${out?'אזל מהמלאי':'הוספה לסל'}</span></button>${out?'':`<div class="card-quantity"><button type="button" data-card-step="1" aria-label="הגדלת כמות: ${esc(p.title)}">+</button><input type="number" inputmode="numeric" min="1" max="${p.stock}" value="1" aria-label="כמות: ${esc(p.title)}"><button type="button" data-card-step="-1" aria-label="הפחתת כמות: ${esc(p.title)}">−</button></div>`}</div></article>`;}

function courseCard(id){const c=courses[id],info=courseInfo[id];return `<article class="course-card" data-audience="${info.audience}"><a href="syllabus.html?c=${id}">${image(c.img,c.title,'loading="lazy"')}</a><div class="course-copy"><span class="tag">${info.audience} · ${info.meetings} מפגשים</span><h3><a href="syllabus.html?c=${id}">${c.title}</a></h3><p>${info.short}</p><div class="course-price"><bdi class="price">${money(+c.price)}</bdi><small>כולל ערכת עבודה</small></div>${btn('לפרטי הקורס','syllabus.html?c='+id,'small light')}</div></article>`;}
function journalCard(a,i){return `<article class="journal-card"><a href="article.html?a=${i}">${image(a.main,a.title,'loading="lazy"')}</a><div><small>${esc(a.cat)} · ${esc(a.time)}</small><h3><a href="article.html?a=${i}">${esc(a.title)}</a></h3><a class="text-link" href="article.html?a=${i}">לקריאת הכתבה ←</a></div></article>`;}
function contactBand(){return `<section class="wrap small-section"><div class="contact-band"><div><h2>מתלבטת לגבי מוצר או קורס?</h2><p>כתבי לליעד, ונמצא יחד בדיוק את מה שמתאים לך.</p></div>${btn('ליצירת קשר','index.html#contact')}</div></section>`;}
function empty(title,text,href='shop.html',label='לחנות'){return `<div class="empty-state"><h2>${title}</h2><p>${text}</p>${btn(label,href)}</div>`;}
function mountShell(){
$('#overlays').innerHTML=`<dialog id="cart-dialog" aria-labelledby="cart-title"><div class="dialog-head"><h2 id="cart-title">הסל שלך</h2><button class="icon-btn" data-close-cart aria-label="סגירת סל הקניות">${icon('close')}</button></div><div class="dialog-body" id="cart-body"></div></dialog><button class="cart-dock" id="cart-dock" data-open-cart aria-label="פתיחת סל הקניות" hidden></button><div id="toast" class="toast" role="status" aria-live="polite"></div>`;
$('#menu-toggle')?.addEventListener('click',()=>togglePanel('mobile-nav','menu-toggle','search-panel','search-toggle'));
$('#search-toggle')?.addEventListener('click',()=>{togglePanel('search-panel','search-toggle','mobile-nav','menu-toggle');if(!$('#search-panel').hidden)$('#search-panel input').focus();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){['mobile-nav','search-panel'].forEach(id=>$('#'+id)&&($('#'+id).hidden=true));['menu-toggle','search-toggle'].forEach(id=>$('#'+id)?.setAttribute('aria-expanded','false'));}});
document.addEventListener('click',e=>{const addButton=e.target.closest('[data-add]');if(addButton){e.preventDefault();add(addButton.dataset.add,addButton.closest('.product-card')?.querySelector('.card-quantity input')?.value||1,addButton,e.detail===0);}const step=e.target.closest('[data-card-step]');if(step){const input=step.parentElement.querySelector('input');input.value=Math.max(1,Math.min(+input.max||1,(+input.value||1)+Number(step.dataset.cardStep)));}const fav=e.target.closest('[data-favorite]');if(fav)saveFavorite(fav.dataset.favorite);if(e.target.closest('[data-open-cart]')){e.preventDefault();openCart();}if(e.target.closest('[data-close-cart]'))closeCart();const change=e.target.closest('[data-cart-change]');if(change){const item=cart.find(x=>x.id===change.dataset.id);if(item){const p=products.find(x=>x.id===item.id);const q=item.qty+Number(change.dataset.cartChange);if(q>p.stock)return toast('הגעת לכמות הזמינה במלאי.');if(q<1)cart=cart.filter(x=>x.id!==item.id);else item.qty=q;updateCart();if(e.detail===0)($(`[data-cart-change="${change.dataset.cartChange}"][data-id="${CSS.escape(item.id)}"]`)||$('#cart-dialog .icon-btn'))?.focus();}}const remove=e.target.closest('[data-remove]');if(remove){cart=cart.filter(x=>x.id!==remove.dataset.remove);updateCart();}});
$('#cart-dialog').addEventListener('click',e=>{if(e.target===$('#cart-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeCart();}});
let lastY=scrollY;addEventListener('scroll',()=>{const d=$('#cart-dock');if(!d||d.hidden||innerWidth>700)return;const y=scrollY;if(Math.abs(y-lastY)<10)return;d.classList.toggle('is-tucked',y>lastY&&y>240);lastY=y;},{passive:true});
renderCart();updateDock();$$('[data-cart-count]').forEach(el=>el.textContent=count());}
function togglePanel(panel,button,other,otherButton){const open=$('#'+panel).hidden;$('#'+panel).hidden=!open;$('#'+button).setAttribute('aria-expanded',String(open));$('#'+other).hidden=true;$('#'+otherButton).setAttribute('aria-expanded','false');}
function openCart(){const d=$('#cart-dialog');if(!d||d.open)return;d.showModal();if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;d.getAnimations().forEach(a=>a.cancel());d.animate([{opacity:0,transform:'translateY(14px) scale(.97)'},{opacity:1,transform:'none'}],{duration:260,easing:'cubic-bezier(.23,1,.32,1)'});}
function closeCart(){const d=$('#cart-dialog');if(!d||!d.open)return;if(matchMedia('(prefers-reduced-motion: reduce)').matches)return d.close();d.getAnimations().forEach(a=>a.cancel());d.animate([{opacity:1,transform:'none'},{opacity:0,transform:'translateY(10px) scale(.98)'}],{duration:160,easing:'cubic-bezier(.4,0,1,1)'}).finished.then(()=>d.close(),()=>d.close());}
function updateDock(){const dock=$('#cart-dock');if(!dock)return;dock.hidden=!cart.length;const n=count();dock.setAttribute('aria-label',`פתיחת סל הקניות: ${n} ${n===1?'פריט':'פריטים'}, ${money(subtotal())}`);dock.innerHTML=`<span class="dock-images" aria-hidden="true">${cart.slice(-3).reverse().map(l=>image(products.find(p=>p.id===l.id).image,'')).join('')}</span><span class="dock-label">הסל שלך<small><span class="dock-count">${n}</span> ${n===1?'פריט':'פריטים'}</small></span><bdi class="dock-total">${money(subtotal())}</bdi>`;}
function addFeedback(p,trigger,keyboard){
 if(trigger){trigger.classList.add('added');const span=trigger.querySelector('span');const label=span?.dataset.label||span?.textContent;if(span){span.dataset.label=label;span.textContent='נוסף לסל';}clearTimeout(trigger._reset);trigger._reset=setTimeout(()=>{trigger.classList.remove('added');if(span)span.textContent=label;},1600);}
 const dock=$('#cart-dock');if(!dock)return;dock.classList.remove('is-tucked');
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const bump=()=>{if(reduced)return;dock.getAnimations().forEach(a=>a.cancel());dock.animate([{transform:'scale(1)'},{transform:'scale(1.05)'},{transform:'scale(1)'}],{duration:300,easing:'cubic-bezier(.23,1,.32,1)'});dock.querySelector('.dock-count')?.animate([{transform:'translateY(5px)',opacity:0},{transform:'none',opacity:1}],{duration:220,easing:'cubic-bezier(.23,1,.32,1)'});};
 if(keyboard||reduced)return bump();
 const source=trigger?.closest('.product-card,.loop-card')?.querySelector('.product-media img,.loop-img img')||$('.product-detail-media>img');
 const landing=dock.querySelector('.dock-images img')||dock;
 if(!source)return bump();
 const s=source.getBoundingClientRect(),e=landing.getBoundingClientRect();if(s.bottom<0||s.top>innerHeight)return bump();
 const size=Math.round(Math.min(130,Math.max(64,Math.min(s.width,s.height)*.62)));
 const ghost=document.createElement('div');ghost.className='cart-flying';ghost.style.cssText=`left:${s.left+s.width/2-size/2}px;top:${s.top+s.height/2-size/2}px;width:${size}px;height:${size}px`;
 const img=document.createElement('img');img.src=p.image;img.alt='';img.className='cart-flying-image';ghost.append(img);document.body.append(ghost);
 const dx=e.left+e.width/2-(s.left+s.width/2),dy=e.top+e.height/2-(s.top+s.height/2),k=Math.max(e.width,30)/size,D=560;
 if(landing!==dock)landing.style.opacity='0';
 const reveal=()=>{ghost.remove();landing.style.opacity='';};
 ghost.animate([{transform:'translateX(0)'},{transform:`translateX(${dx}px)`}],{duration:D,easing:'cubic-bezier(.3,0,.2,1)'});
 img.animate([{transform:'translateY(0) scale(1)',opacity:1},{transform:`translateY(${dy}px) scale(${k})`,opacity:.92}],{duration:D,easing:'cubic-bezier(.55,-.45,.75,1)'}).finished.then(()=>{reveal();bump();},reveal);
}
function cartLines(edit=true){return cart.map(l=>{const p=products.find(p=>p.id===l.id);return `<div class="cart-line">${image(p.image,'')}<div><h3><a href="product.html?id=${encodeURIComponent(p.id)}">${esc(p.title)}</a></h3><p class="cart-line-price"><bdi class="price">${money(p.price*l.qty)}</bdi>${l.qty>1?`<small><bdi>${money(p.price)}</bdi> ליחידה</small>`:''}</p><div class="cart-line-meta">${edit?`<div class="quantity"><button type="button" data-cart-change="-1" data-id="${esc(l.id)}" aria-label="${l.qty===1?'הסרה מהסל':'הפחתת כמות'}: ${esc(p.title)}">−</button><output aria-label="כמות">${l.qty}</output><button type="button" data-cart-change="1" data-id="${esc(l.id)}" aria-label="הגדלת כמות: ${esc(p.title)}" ${l.qty>=p.stock?'disabled':''}>+</button></div><button type="button" class="remove-btn" data-remove="${esc(l.id)}" aria-label="הסרה מהסל: ${esc(p.title)}">הסרה</button>`:`<span>כמות: ${l.qty}</span>`}</div></div></div>`;}).join('');}
function renderCart(){const body=$('#cart-body');if(!body)return;if(!cart.length){body.innerHTML=empty('הסל מחכה לבחירות שלך','מוצרים, גוונים וכלים לעבודה שתאהבי.');return;}const sum=subtotal();body.innerHTML=cartLines()+`<div class="cart-summary"><p class="shipping-note">${sum>=SHIPPING.freeFrom?'הסל שלך זכאי למשלוח חינם.':`עוד ${money(SHIPPING.freeFrom-sum)} למשלוח חינם.`}</p><div class="total-row"><span>סכום המוצרים</span><bdi class="price">${money(sum)}</bdi></div><p class="form-help">המשלוח מחושב בשלב הבא.</p>${btn('להמשך ההזמנה','checkout.html')}<button class="text-link" data-close-cart>להמשיך לגלות</button></div>`;}
function categoryTile(id){const p=products.find(p=>p.category===id);const n=products.filter(p=>p.category===id).length;return `<a class="category-item" href="shop.html?category=${id}"><div class="category-image">${image(p.image,categories[id],'loading="lazy"')}</div><h3>${categories[id]}</h3><small>${n} מוצרים וגוונים</small></a>`;}
const featuredIds=['bell-bell-color-builder-003','koyo-koyo-kit-french-koyo-kit-french-kit','buba-buba-drill-buba-drill','sun-sun-1s-sun-1s'];
function featured(){return featuredIds.map(id=>products.find(p=>p.id===id)).filter(Boolean);}
function home(){return `<section class="hero wrap"><div class="hero-grid"><div class="hero-copy"><p class="eyebrow">LIAD · NAIL STUDIO & ACADEMY</p><h1>יותר מציפורניים.<span class="script">כל מה שאת יכולה להיות.</span></h1><p class="lead">המוצרים הנכונים בידיים שלך. הידע שייקח אותך קדימה. חנות מקצועית ואקדמיה בוטיקית, עם ליעד לצידך בכל שלב.</p><div class="actions">${btn('לגלות את החנות','shop.html')}${btn('להכיר את האקדמיה','courses.html','light')}</div><p class="hero-footnote">נבחר בסטודיו. נלמד מקרוב. נעשה באהבה.</p></div><div class="hero-art">${image('assets/img/opening/liad-real.webp','ליעד, מייסדת הסטודיו והאקדמיה','fetchpriority="high"')}<div class="photo-note"><div><b>נעים להכיר, אני ליעד.</b><small>15 שנות ניסיון · ליווי אישי · כיתות בוטיק</small></div><span class="signature">בידיים טובות</span></div></div></div></section><div class="promise-strip wrap"><span><b>מוצרים שנבחרו בסטודיו</b></span><span>עד 3 תלמידות בכיתה</span><span>ערכת עבודה בכל קורס</span><span>איסוף עצמי מבנימינה</span></div><section class="section wrap" id="categories"><div class="section-head"><div><p class="eyebrow">FIND YOUR ESSENTIALS</p><h2>בדיוק מה <span class="script">שאת צריכה.</span></h2><p>מהצבע הראשון ועד הפרט האחרון בעמדת העבודה.</p></div><a class="text-link" href="shop.html">לכל ${products.length} המוצרים ←</a></div><div class="category-grid">${['gel-polish','builder-gel','bases','polygel','machines','lamps'].map(categoryTile).join('')}</div></section><section class="section wrap" id="products"><div class="section-head"><div><p class="eyebrow">LIAD'S EDIT</p><h2>מהשולחן שלי, <span class="script">לסטודיו שלך.</span></h2><p>מבחר המוצרים והכלים של LIAD, במקום אחד.</p></div>${btn('לכל המוצרים','shop.html','light')}</div><div class="product-grid">${featured().map(productCard).join('')}</div></section><section class="section tinted" id="about"><div class="split wrap"><div class="split-copy"><p class="eyebrow">A PERSONAL TOUCH</p><h2>מאחורי כל עבודה יפה,<br><span class="script">יש יד מכוונת.</span></h2><p class="lead">אני ליעד. אחרי שנים ליד שולחן העבודה, אני יודעת כמה משמעות יש לחומר הנכון — ולמישהי שמאמינה בך בדרך.</p><p>ב־LIAD חיברתי בין שני העולמות שלי: מוצרים לעבודה מקצועית, והוראה אישית שמתחילה ביסודות וממשיכה גם אחרי הקורס.</p><div class="actions">${btn('קצת יותר עליי','index.html#about','light')}</div><div class="facts"><div><strong>15</strong><span>שנות ניסיון</span></div><div><strong>3</strong><span>תלמידות לכל היותר</span></div><div><strong>4</strong><span>מסלולי לימוד</span></div></div></div>${image('assets/img/academy/studio.webp','ליעד מדריכה תלמידות בסטודיו','class="split-photo" loading="lazy"')}</div></section><section class="section wrap" id="academy"><div class="section-head"><div><p class="eyebrow">LIAD ACADEMY</p><h2><span class="script">ללמוד, להתמקצע</span> ולהצליח.</h2><p>ארבעה מסלולים. כיתות קטנות. מקום גדול להתפתח.</p></div>${btn('לכל הקורסים','courses.html','light')}</div><div class="courses-grid">${Object.keys(courses).map(courseCard).join('')}</div></section><section class="section wrap" id="journal"><div class="section-head"><div><p class="eyebrow">THE JOURNAL</p><h2>קצת ידע, <span class="script">הרבה השראה.</span></h2></div><a href="index.html#journal" class="text-link">למגזין של LIAD ←</a></div><div class="journal-grid">${articles.map(journalCard).join('')}</div></section>${contactBand()}`;}
const askLink=t=>'index.html?topic='+encodeURIComponent(t)+'#contact';
const playIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5.5v13l11-6.5Z" fill="currentColor" stroke="none"/></svg>';
function trackRow(id){const c=courses[id],info=courseInfo[id],url='syllabus.html?c='+id;return `<article class="ac-track" id="track-${id}"><a class="ac-track-media" href="${url}" tabindex="-1" aria-hidden="true">${image(c.img,'','loading="lazy" decoding="async"')}</a><div class="ac-track-body"><p class="ac-track-num"><span dir="ltr">${info.n}</span> · ${info.audience}</p><h3><a href="${url}">${c.title}</a></h3><p class="ac-fit">${info.fit}</p><ul class="ac-highlights">${info.highlights.map(h=>`<li>${h}</li>`).join('')}</ul></div><div class="ac-track-facts"><dl><div><dt>מפגשים</dt><dd>${info.meetings} מפגשים של 4 שעות</dd></div><div><dt>כיתה</dt><dd>עד 3 תלמידות</dd></div><div><dt>כלול</dt><dd>${info.kit}, תעודת הסמכה</dd></div></dl><p class="ac-price"><bdi>${money(+c.price)}</bdi>${c.note?`<small>${c.note}</small>`:''}</p><div class="ac-track-actions"><a class="btn" href="${url}">לסילבוס המלא</a><a class="text-link" href="${askLink(c.title)}">שאלה על המסלול</a></div></div></article>`;}
function stories(){return `<div class="story-strip">${[1,2,3,4].map(n=>`<figure class="story"><video preload="none" playsinline poster="assets/img/courses/testimonial-${n}-poster.jpg" aria-label="סרטון המלצה ${n} מתוך 4"><source src="assets/video/testimonial-${n}.mp4" type="video/mp4"></video><button class="story-play" type="button" aria-label="ניגון סרטון המלצה ${n}">${playIcon}</button><figcaption>הסיפור שלה · <span dir="ltr">0${n}</span></figcaption></figure>`).join('')}</div>`;}
function wireStories(){const figs=$$('.story'),vids=figs.map(f=>f.querySelector('video'));figs.forEach((f,i)=>{const v=vids[i];f.querySelector('.story-play').addEventListener('click',()=>{v.controls=true;v.play().catch(()=>{});});v.addEventListener('play',()=>{vids.forEach(x=>{if(x!==v&&!x.paused)x.pause();});f.classList.add('is-playing');});v.addEventListener('pause',()=>f.classList.remove('is-playing'));v.addEventListener('ended',()=>{v.controls=false;v.currentTime=0;});});const io=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting&&!e.target.paused)e.target.pause();}),{threshold:.2});vids.forEach(v=>io.observe(v));}
function wireCine(){const vids=$$('.ac-cine video'),btn=$('.ac-cine-toggle');if(!vids.length)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let wanted=!reduced;const sync=()=>{btn.setAttribute('aria-pressed',String(!wanted));btn.setAttribute('aria-label',wanted?'עצירת הסרטון':'הפעלת הסרטון');btn.classList.toggle('is-paused',!wanted);};const run=on=>vids.forEach(v=>{if(on&&wanted&&v.offsetParent)v.play().catch(()=>{});else v.pause();});new IntersectionObserver(es=>run(es[0].isIntersecting),{threshold:.05}).observe($('.ac-cine'));btn.addEventListener('click',()=>{wanted=!wanted;sync();run(true);});sync();}
function academy(){const ids=Object.keys(courses);const vid=cls=>`<video class="${cls}" muted loop playsinline preload="metadata" poster="assets/img/academy/tour-poster.jpg"${cls==='ac-cine-bg'?' aria-hidden="true" tabindex="-1"':' aria-label="סיור בסטודיו ובכיתות של LIAD, ללא קול"'}><source src="assets/video/brand-3.mp4" type="video/mp4"></video>`;const band='<span>ללמוד</span><i>·</i><span>להתמקצע</span><i>·</i><span>להצליח</span><i>·</i><span dir="ltr">LIAD ACADEMY</span><i>·</i>';return `<section class="ac-cine" aria-labelledby="ac-title">${vid('ac-cine-bg')}<div class="ac-cine-shade" aria-hidden="true"></div><div class="ac-cine-inner wrap"><div class="ac-cine-copy"><nav class="crumb" aria-label="פירורי לחם"><a href="index.html">בית</a><span aria-hidden="true">/</span><span>האקדמיה</span></nav><p class="eyebrow">LIAD ACADEMY · BINYAMINA · NETANYA</p><h1 class="ac-title" id="ac-title">ללמוד, להתמקצע<br>ולהצליח.</h1><p class="lead">כיתת בוטיק של עד 3 תלמידות, מורה מוסמכת עם 15 שנות ניסיון, וליווי אישי ומקצועי גם אחרי הקורס.</p><div class="actions"><a class="btn invert" href="#tracks">למסלולי הלימוד</a><a class="btn light invert" href="${askLink('ייעוץ לבחירת מסלול לימודים')}">שיחת ייעוץ</a></div></div><figure class="ac-cine-frame">${vid('ac-cine-fg')}<button type="button" class="ac-cine-toggle" aria-pressed="false" aria-label="עצירת הסרטון"><svg viewBox="0 0 24 24" aria-hidden="true"><path class="i-pause" d="M8 5v14M16 5v14"/><path class="i-play" d="M8 5.5v13l11-6.5Z" fill="currentColor" stroke="none"/></svg></button><figcaption>סיור בסטודיו ובכיתות</figcaption></figure></div></section><div class="ac-marquee" aria-hidden="true"><div class="ac-marquee-track">${band.repeat(6)}</div></div><section class="ac-values wrap" aria-label="מה מייחד את הלימודים"><div><b>עד 3</b><span>תלמידות בכיתה, כדי שכל אחת תקבל יחס אישי</span></div><div><b>15</b><span>שנות ניסיון של ליעד בתחום, כמורה מוסמכת</span></div><div><b>ליווי</b><span>אישי ומקצועי שנמשך גם אחרי סיום הקורס</span></div><div><b>הסמכה</b><span>תעודה מקצועית וערכת עבודה בכל מסלול</span></div></section><section class="ac-tracks wrap" id="tracks"><header class="ac-head"><p class="eyebrow">THE PROGRAMS</p><h2>ארבעה מסלולי לימוד</h2><p>כל מסלול משלב לימוד עיוני ותרגול מעשי. בחרי לפי השלב שבו את נמצאת, ופתחי את הסילבוס המלא לפרטים.</p></header><nav class="ac-jump" aria-label="מעבר למסלול">${ids.map(id=>`<a href="#track-${id}">${courses[id].title.replace('קורס ','')}</a>`).join('')}</nav><div class="ac-track-list">${ids.map(trackRow).join('')}</div></section><section class="ac-method"><div class="wrap"><header class="ac-head"><p class="eyebrow">HOW WE LEARN</p><h2>לומדות מקרוב, מתרגלות באמת</h2></header><ol class="ac-steps"><li><span dir="ltr">01</span><h3>יסודות ותיאוריה</h3><p>השיעור הראשון עיוני ופרונטלי: מבנה הציפורן, חומרי העבודה, הכלים ושיטות העבודה, עם תרגול ראשון על יד אימון.</p></li><li><span dir="ltr">02</span><h3>תרגול מעשי</h3><p>ברוב המפגשים עובדות בפועל, על מודליסטיות, בליווי צמוד של ליעד ובקצב שמאפשר לשאול ולחזור על כל שלב.</p></li><li><span dir="ltr">03</span><h3>הסמכה וליווי</h3><p>בסיום מקבלות תעודת הסמכה מקצועית ואת ערכת העבודה, וממשיכות לקבל ליווי אישי ומקצועי גם אחרי הלימודים.</p></li></ol></div></section><section class="ac-stories wrap"><header class="ac-head"><p class="eyebrow">STUDENT STORIES</p><h2>מהכיתה, בקול שלהן</h2><p>תלמידות האקדמיה משתפות בחוויה שלהן ב־LIAD.</p></header>${stories()}</section><section class="ac-faq wrap"><header class="ac-head"><h2>שאלות נפוצות</h2></header><div class="faq-list"><details><summary>צריך ניסיון קודם?</summary><p>קורס לק ג׳ל ומבנה אנטומי מתחיל מהיסודות. קורס הבנייה באקריג׳ל מיועד למקצועיות בתחום הלק ג׳ל. בקורס הנערות לומדות להכיר את התחום בקבוצה קטנה. להתאמה אישית אפשר לפנות לליעד.</p></details><details><summary>מה כלול במחיר הקורס?</summary><p>כל הקורסים כוללים ערכת עבודה, לימוד עיוני ומעשי ותעודת הסמכה. בכל סילבוס מופיעה רשימת הערכה המדויקת.</p></details><details><summary>מתי הקורס הקרוב ואיפה לומדות?</summary><p>מועדי הפתיחה, הזמינות ומיקום הלימודים נקבעים בתיאום. <a class="text-link" href="${askLink('מועדי קורסים')}">כתבי לליעד</a> כדי לשמוע על המחזור הבא.</p></details><details><summary>אפשר לפרוס לתשלומים?</summary><p>בסילבוסים של לק ג׳ל ומבנה אנטומי ושל בנייה באקריג׳ל מצוינת אפשרות לפריסה לתשלומים. לפרטים ולשאר המסלולים, פני לליעד.</p></details></div></section><section class="ac-contact wrap"><div><h2>יש לך שאלה על מסלול מסוים?</h2><p>בחרי את הקורס, וטופס הפנייה ייפתח עם הנושא כבר ממולא.</p></div><div class="ac-contact-links">${ids.map(id=>`<a href="${askLink(courses[id].title)}">${courses[id].title.replace('קורס ','')}</a>`).join('')}</div></section>`;}
function syllabus(){const id=params.get('c'),c=courses[id];if(!c)return notFound('הקורס לא נמצא','courses.html','לכל הקורסים');document.title=c.title+' · LIAD';const info=courseInfo[id],ask=askLink(c.title);const list=(items,cls='check-list')=>`<ul class="${cls}">${items.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`;const others=Object.keys(courses).filter(k=>k!==id);return `${crumb(c.title,'<a href="courses.html">האקדמיה</a><span aria-hidden="true">/</span>')}<header class="sy-hero wrap"><div class="sy-hero-copy"><p class="eyebrow">${c.en}</p><h1>${c.title}</h1><p class="lead">${info.fit}</p><dl class="sy-facts"><div><dt>מפגשים</dt><dd>${info.meetings}</dd></div><div><dt>שעות לימוד</dt><dd>${info.meetings*4}</dd></div><div><dt>בכיתה</dt><dd>עד 3</dd></div><div><dt>מחיר</dt><dd><bdi>${money(+c.price)}</bdi></dd></div></dl><div class="actions"><a class="btn" href="${ask}">לפרטים ולהרשמה</a><a class="btn light" href="#sy-structure">למבנה המפגשים</a></div></div><figure class="sy-hero-media">${image(c.img,c.title,'fetchpriority="high"')}</figure></header><nav class="sy-tabs" aria-label="תוכן הסילבוס"><div class="wrap"><a href="#sy-fit">למי מתאים</a><a href="#sy-learn">מה לומדים</a><a href="#sy-structure">מבנה המפגשים</a><a href="#sy-get">מה מקבלים</a><a href="#sy-kit">ערכת העבודה</a></div></nav><div class="sy-layout wrap"><div class="sy-main"><section class="sy-sec" id="sy-fit"><h2>למי הקורס מתאים</h2><p>${esc(c.intro)}</p></section><section class="sy-sec" id="sy-learn"><h2>מה לומדים</h2>${c.learn?`<p>${esc(c.learn)}</p>`:list(c.learnList)}${c.theory?`<div class="sy-two"><div><h3>החלק העיוני</h3>${list(c.theory,'dot-list')}</div><div><h3>החלק המעשי</h3>${list(c.practice,'dot-list')}</div></div>`:''}</section><section class="sy-sec" id="sy-structure"><h2>מבנה המפגשים</h2><p class="sy-sub">${c.meta} · ${info.meetings*4} שעות לימוד</p><ol class="sy-timeline">${c.lessons.map(([t,x])=>{const [num,kind]=t.split(' · ');return `<li><div class="sy-t-head"><b>${esc(num)}</b>${kind?`<span>${esc(kind)}</span>`:''}</div><p>${esc(x)}</p></li>`;}).join('')}</ol></section><section class="sy-sec" id="sy-get"><h2>מה מקבלים</h2>${list(c.get)}</section><section class="sy-sec" id="sy-kit"><h2>ערכת העבודה</h2><p class="sy-sub">${c.kit.length} פריטים כלולים בערכה, לפי הסילבוס.</p>${list(c.kit,'kit-list')}</section></div><aside class="sy-aside" aria-label="סיכום הקורס"><p class="sy-aside-kicker">${info.audience} · ${info.meetings} מפגשים</p><p class="sy-price"><bdi>${money(+c.price)}</bdi></p><p class="sy-price-note">מחיר הקורס, כולל ערכת עבודה${c.note?`<br>${c.note}`:''}</p><ul><li>${info.meetings} מפגשים של 4 שעות</li><li>כיתת בוטיק, עד 3 תלמידות</li><li>תעודת הסמכה מקצועית</li><li>ליווי אישי גם אחרי הקורס</li></ul><a class="btn" href="${ask}">לפרטים ולהרשמה</a><p class="form-help">מועדי פתיחה ומיקום הלימודים בתיאום עם ליעד. הטופס ייפתח עם שם הקורס.</p><a class="text-link" href="assets/syllabi/${id}.jpg" target="_blank" rel="noopener">לסילבוס המקורי</a></aside></div><section class="sy-others wrap"><h2>מסלולים נוספים</h2><div class="sy-others-grid">${others.map(k=>`<a href="syllabus.html?c=${k}">${image(courses[k].img,'','loading="lazy"')}<span><b>${courses[k].title}</b><small>${courseInfo[k].meetings} מפגשים · <bdi>${money(+courses[k].price)}</bdi></small></span></a>`).join('')}</div></section>`;}
let catalogState={category:params.get('category')||'',q:params.get('q')||'',brand:params.get('brand')||'',sort:params.get('sort')||'default',stock:params.get('stock')==='1',page:Math.max(1,parseInt(params.get('page'))||1)};
function shop(){return `${crumb('החנות')}<div class="wrap">${heading(params.get('favorites')==='1'?'המועדפים שלך':'החנות של LIAD',params.get('favorites')==='1'?'המוצרים שאהבת, במקום אחד.':`${products.length} מוצרים וגוונים לעבודה מקצועית.`,'THE LIAD SHOP')}<div class="catalog-layout"><aside class="catalog-sidebar" id="catalog-sidebar" aria-label="סינון מוצרים"><h2>מה את מחפשת?</h2><div class="categories-filter">${[['','כל המוצרים'],...Object.entries(categories)].map(([id,label])=>`<button class="category-filter ${catalogState.category===id?'active':''}" data-category="${id}" aria-pressed="${catalogState.category===id}"><span>${label}</span><small>${id?products.filter(p=>p.category===id).length:products.length}</small></button>`).join('')}<button class="category-expand" type="button" id="category-expand" aria-expanded="false">הצגת כל הקטגוריות (${Object.keys(categories).length})</button></div><div class="filter-group"><h2>מותג</h2><label class="form-field" for="brand-filter">בחירת מותג<select id="brand-filter"><option value="">כל המותגים</option>${[...new Set(products.map(p=>p.brand))].sort().map(b=>`<option ${catalogState.brand===b?'selected':''} value="${esc(b)}">${esc(b)}</option>`).join('')}</select></label><label><input type="checkbox" id="stock-filter" ${catalogState.stock?'checked':''}> מוצרים במלאי בלבד</label></div><div class="filter-group"><button class="text-link" id="reset-filters">ניקוי הסינון</button></div></aside><section aria-label="קטלוג מוצרים"><div class="catalog-tools"><input type="search" id="catalog-search" aria-label="חיפוש בחנות" placeholder="חפשי מוצר, מותג או מספר גוון" value="${esc(catalogState.q)}"><button class="btn small light mobile-filter-toggle" id="filter-toggle" aria-expanded="false" aria-controls="catalog-sidebar">סינון מוצרים${arrow}</button><select id="sort-filter" aria-label="מיון מוצרים"><option value="default">סדר הקטלוג</option><option value="price-asc">מחיר: מהנמוך לגבוה</option><option value="price-desc">מחיר: מהגבוה לנמוך</option><option value="name">לפי שם המוצר</option></select></div><div class="catalog-count" aria-live="polite"><span id="result-count"></span><span id="active-category"></span></div><div class="product-grid" id="catalog-products"></div><nav class="pagination" id="pagination" aria-label="דפדוף מוצרים"></nav></section></div></div>${contactBand()}`;}
function renderCatalog(){let list=products.filter(p=>(!catalogState.category||p.category===catalogState.category)&&(!catalogState.brand||p.brand===catalogState.brand)&&(!catalogState.stock||p.stock>0)&&(params.get('favorites')!=='1'||favorites.includes(p.id)));const q=catalogState.q.trim().toLocaleLowerCase();if(q)list=list.filter(p=>[p.title,p.brand,p.shade,p.description,p.line].join(' ').toLocaleLowerCase().includes(q));if(catalogState.sort==='price-asc')list.sort((a,b)=>a.price-b.price);if(catalogState.sort==='price-desc')list.sort((a,b)=>b.price-a.price);if(catalogState.sort==='name')list.sort((a,b)=>a.title.localeCompare(b.title,'he'));const pages=Math.max(1,Math.ceil(list.length/24));catalogState.page=Math.min(catalogState.page,pages);$('#result-count').textContent=`${list.length} מוצרים${list.length?` · עמוד ${catalogState.page} מתוך ${pages}`:''}`;$('#active-category').textContent=categories[catalogState.category]||'';$('.page-heading h1').textContent=params.get('favorites')==='1'?'המועדפים שלך':(categories[catalogState.category]||'כל המוצרים');if(params.get('favorites')!=='1')$('.page-heading .lead').textContent=catalogState.category?`${products.filter(p=>p.category===catalogState.category).length} מוצרים בקטגוריה.`:`${products.length} מוצרים וגוונים לעבודה מקצועית.`;$('#catalog-products').innerHTML=list.length?list.slice((catalogState.page-1)*24,catalogState.page*24).map(productCard).join(''):empty(params.get('favorites')==='1'&&!favorites.length?'עדיין לא שמרת מוצרים':'לא נמצאו מוצרים',params.get('favorites')==='1'&&!favorites.length?'לחצי על הלב לצד מוצר שאהבת כדי לשמור אותו כאן.':'נסי לחפש בשם אחר או לנקות את הסינון.','shop.html','לכל המוצרים');const nums=[...new Set([1,...[catalogState.page-1,catalogState.page,catalogState.page+1].filter(n=>n>0&&n<=pages),pages])].sort((a,b)=>a-b);$('#pagination').innerHTML=pages>1?`<button data-page="${catalogState.page-1}" aria-label="העמוד הקודם" ${catalogState.page===1?'disabled':''}>→</button>${nums.map((n,i)=>`${i&&n-nums[i-1]>1?'<span aria-hidden="true">…</span>':''}<button data-page="${n}" class="${n===catalogState.page?'active':''}" ${n===catalogState.page?'aria-current="page"':''} aria-label="עמוד ${n}">${n}</button>`).join('')}<button data-page="${catalogState.page+1}" aria-label="העמוד הבא" ${catalogState.page===pages?'disabled':''}>←</button>`:'';$$('[data-category]').forEach(el=>{el.classList.toggle('active',el.dataset.category===catalogState.category);el.setAttribute('aria-pressed',String(el.dataset.category===catalogState.category));});const query=new URLSearchParams();for(const [k,v] of Object.entries(catalogState)){if(v&&!(k==='page'&&v===1)&&!(k==='sort'&&v==='default'))query.set(k,v===true?'1':v);}if(params.get('favorites')==='1')query.set('favorites','1');history.replaceState(null,'',page+(query.size?'?'+query.toString():''));}
function wireShop(){$('#category-expand')?.addEventListener('click',e=>{const open=$('.categories-filter').classList.toggle('expanded');e.currentTarget.setAttribute('aria-expanded',String(open));e.currentTarget.textContent=open?'הצגת פחות':'הצגת כל הקטגוריות';});if(catalogState.category)$('.categories-filter').classList.add('expanded');$('#sort-filter').value=catalogState.sort;renderCatalog();$('#catalog-search').addEventListener('input',e=>{catalogState.q=e.target.value;catalogState.page=1;renderCatalog();});$('#brand-filter').addEventListener('change',e=>{catalogState.brand=e.target.value;catalogState.page=1;renderCatalog();});$('#stock-filter').addEventListener('change',e=>{catalogState.stock=e.target.checked;catalogState.page=1;renderCatalog();});$('#sort-filter').addEventListener('change',e=>{catalogState.sort=e.target.value;catalogState.page=1;renderCatalog();});$('#reset-filters').addEventListener('click',()=>{catalogState={category:'',q:'',brand:'',sort:'default',stock:false,page:1};$('#catalog-search').value='';$('#brand-filter').value='';$('#stock-filter').checked=false;$('#sort-filter').value='default';renderCatalog();});$('#filter-toggle').addEventListener('click',()=>{const open=$('#catalog-sidebar').classList.toggle('open');$('#filter-toggle').setAttribute('aria-expanded',String(open));if(open)$('#catalog-sidebar').scrollIntoView({block:'start'});});document.addEventListener('click',e=>{const c=e.target.closest('[data-category]');if(c){catalogState.category=c.dataset.category;catalogState.page=1;renderCatalog();}const p=e.target.closest('[data-page]');if(p){catalogState.page=+p.dataset.page;renderCatalog();$('#catalog-search').scrollIntoView({block:'start'});}});}
function productPage(){const p=products.find(p=>p.id===params.get('id'));if(!p)return notFound('המוצר לא נמצא','shop.html','לחנות');document.title=p.title+' · LIAD';const siblings=products.filter(x=>x.line===p.line&&x.brand===p.brand);const related=products.filter(x=>x.category===p.category&&x.id!==p.id&&x.line!==p.line).slice(0,4);const more=related.length<4?products.filter(x=>x.category===p.category&&x.id!==p.id&&!related.includes(x)).slice(0,4-related.length):[];const out=p.stock<=0;const shades=siblings.length>1?`<div class="shade-picker${siblings.length>18?' is-collapsed':''}"><p class="shade-label">גוון: <b>${esc(p.shade||p.title)}</b><small>${siblings.length} גוונים בסדרה</small></p><div class="shade-grid">${siblings.map(s=>`<a class="shade${s.id===p.id?' is-current':''}${s.stock<=0?' is-out':''}" href="product.html?id=${encodeURIComponent(s.id)}"${s.id===p.id?' aria-current="true"':''} aria-label="גוון ${esc(s.shade||s.title)}${s.stock<=0?', אזל מהמלאי':''}" title="${esc(s.shade||s.title)}">${image(s.image,'','loading="lazy" decoding="async"')}<span dir="ltr">${esc(s.shade||'')}</span></a>`).join('')}</div>${siblings.length>18?`<button type="button" class="shade-more" aria-expanded="false">הצגת כל ${siblings.length} הגוונים</button>`:''}</div>`:'';return `${crumb(p.title,`<a href="shop.html">החנות</a><span aria-hidden="true">/</span><a href="shop.html?category=${p.category}">${categories[p.category]}</a><span aria-hidden="true">/</span>`)}<section class="product-detail wrap"><div class="product-detail-media">${image(p.image,p.title,'fetchpriority="high"')}<button type="button" class="favorite" data-favorite="${esc(p.id)}" aria-pressed="${favorites.includes(p.id)}" aria-label="${favorites.includes(p.id)?'הסרה מהמועדפים':'שמירה במועדפים'}: ${esc(p.title)}">${icon('heart')}</button></div><div class="product-summary"><p class="product-brand"><span dir="ltr">${esc(p.brand)}</span> · <a href="shop.html?category=${p.category}">${categories[p.category]}</a></p><h1>${esc(p.title)}</h1><div class="price-row"><bdi class="price">${money(p.price)}</bdi><span class="stock${out?' is-out':''}">${out?'אזל מהמלאי':'במלאי לפי הקטלוג'}</span></div>${shades}<div class="buy-row"><button class="btn" id="product-add" ${out?'disabled':''}><span>${out?'אזל מהמלאי':'הוספה לסל'}</span></button><div class="quantity"><button type="button" id="quantity-minus" aria-label="הפחתת כמות">−</button><input type="number" inputmode="numeric" id="product-quantity" min="1" max="${p.stock}" value="1" aria-label="כמות המוצר" ${out?'disabled':''}><button type="button" id="quantity-plus" aria-label="הגדלת כמות">+</button></div></div><p class="product-description">${esc(p.description)}</p><ul class="detail-notes"><li><b>משלוח</b><span>${money(SHIPPING.flat)} · ללא עלות בקנייה מ־${money(SHIPPING.freeFrom)}</span></li><li><b>איסוף עצמי</b><span>מתחם הפיל, בנימינה · בתיאום מראש</span></li><li><b>הזמנה</b><span>בקשת הזמנה במייל, ללא חיוב באתר</span></li></ul><a class="text-link" href="${askLink(p.title)}">שאלה על המוצר</a></div></section>${related.length+more.length?`<section class="section wrap related"><div class="section-head"><h2>עוד מ${categories[p.category]}</h2><a class="text-link" href="shop.html?category=${p.category}">לכל המוצרים בקטגוריה</a></div><div class="product-grid">${[...related,...more].map(productCard).join('')}</div></section>`:''}`;}
function wireProduct(){const p=products.find(p=>p.id===params.get('id'));if(!p)return;$('.shade-more')?.addEventListener('click',e=>{const box=e.currentTarget.closest('.shade-picker'),open=box.classList.toggle('is-collapsed')===false;e.currentTarget.setAttribute('aria-expanded',String(open));e.currentTarget.textContent=open?'הצגת פחות גוונים':`הצגת כל ${box.querySelectorAll('.shade').length} הגוונים`;});const box=$('.shade-picker.is-collapsed'),cur=$('.shade.is-current');if(box&&cur&&[...box.querySelectorAll('.shade')].indexOf(cur)>=18)$('.shade-more').click();const q=$('#product-quantity');$('#quantity-minus').addEventListener('click',()=>{q.value=Math.max(1,(+q.value||1)-1);});$('#quantity-plus').addEventListener('click',()=>{q.value=Math.max(1,Math.min(p.stock,(+q.value||1)+1));});$('#product-add').addEventListener('click',e=>add(p.id,q.value,e.currentTarget,e.detail===0));}
function checkout(){if(!cart.length)return `<section class="section wrap">${empty('הסל שלך עדיין ריק','בחרי את המוצרים שלך ואז נחזור לכאן.')}</section>`;return `${crumb('המשך ההזמנה','<a href="shop.html">החנות</a><span aria-hidden="true">/</span>')}<div class="wrap">${heading('עוד רגע, <span class="script">זה שלך.</span>','נכין את פרטי הבקשה שלך, להמשך תיאום אישי מול ליעד.','YOUR LIAD ORDER')}<div class="notice">${PAY.cardEndpoint||PAY.bitLink?'אפשר לשלם באמצעי התשלום הזמינים למטה, או לשלוח בקשת הזמנה ולתאם תשלום מול ליעד. המלאי ומועד האספקה מאושרים אישית.':'בשלב זה ההזמנה באתר היא בקשה לתיאום במייל, ללא חיוב באתר. המחיר, המלאי ומועד האספקה יאושרו על ידי ליעד לפני התשלום.'}</div><div class="checkout-layout"><form id="checkout-form" class="form-panel"><h2>הפרטים שלך</h2><div class="form-grid"><label class="form-field">שם מלא<input type="text" name="name" autocomplete="name" minlength="2" required></label><label class="form-field">טלפון<input type="tel" name="phone" autocomplete="tel" pattern="[0-9+\\(\\)\\- ]{9,16}" required></label><label class="form-field full">אימייל<input type="email" name="email" autocomplete="email" required></label></div><fieldset><legend>איך תרצי לקבל את ההזמנה?</legend><div class="shipping-options"><label class="shipping-option"><input type="radio" name="shipping" value="delivery" checked><span>משלוח עד הבית<small>מ־${money(SHIPPING.freeFrom)} — ללא עלות</small></span></label><label class="shipping-option"><input type="radio" name="shipping" value="pickup"><span>איסוף עצמי<small>בנימינה · ללא עלות · בתיאום</small></span></label></div></fieldset><div class="form-grid" id="address-fields"><label class="form-field">עיר<input type="text" name="city" autocomplete="address-level2" minlength="2" required></label><label class="form-field">רחוב ומספר<input type="text" name="street" autocomplete="street-address" minlength="2" required></label></div><fieldset><legend>איך תרצי לשלם?</legend><div class="shipping-options pay-options"><label class="shipping-option${PAY.cardEndpoint?'':' is-soon'}"><input type="radio" name="payment" value="card" ${PAY.cardEndpoint?'':'disabled'}><span>כרטיס אשראי<small>${PAY.cardEndpoint?'דף תשלום מאובטח של חברת הסליקה':'בקרוב · יופעל עם חיבור חברת הסליקה'}</small></span></label><label class="shipping-option${PAY.bitLink?'':' is-soon'}"><input type="radio" name="payment" value="bit" ${PAY.bitLink?'':'disabled'}><span>Bit<small>${PAY.bitLink?'תשלום באפליקציית Bit':'בקרוב · יופעל עם חשבון Bit לעסקים'}</small></span></label><label class="shipping-option"><input type="radio" name="payment" value="request" checked><span>תיאום תשלום מול ליעד<small>שליחת בקשת הזמנה במייל, ללא חיוב באתר</small></span></label></div></fieldset><label class="form-field full small-section">משהו נוסף שכדאי שנדע?<textarea name="notes" rows="3" maxlength="1000" placeholder="פרטים לאיסוף, שאלות על המוצרים או הערות להזמנה"></textarea></label><button type="submit" class="btn">להכנת בקשת ההזמנה${arrow}</button><p class="form-help">הפרטים נועדו לתיאום ההזמנה בלבד. <a class="text-link" href="privacy.html">מידע על פרטיות</a></p><div class="form-feedback" id="checkout-feedback" aria-live="polite"></div></form><aside class="checkout-summary" id="checkout-summary" aria-label="סיכום ההזמנה"></aside></div></div>`;}
function shippingAmount(){return $('input[name=shipping]:checked')?.value==='pickup'||subtotal()>=SHIPPING.freeFrom?0:SHIPPING.flat;}
function renderCheckoutSummary(){const el=$('#checkout-summary');if(!el)return;const sum=subtotal(),shipping=shippingAmount();el.innerHTML=`<h2>הבחירות שלך</h2>${cartLines(false)}<div class="total-row"><span>מוצרים</span><bdi>${money(sum)}</bdi></div><div class="total-row"><span>משלוח</span><bdi>${shipping?money(shipping):'ללא עלות'}</bdi></div><div class="total-row grand"><span>סך הכול</span><bdi>${money(sum+shipping)}</bdi></div><a class="text-link" href="shop.html">להמשיך לקנות ←</a>`;}
function wireCheckout(){const form=$('#checkout-form');if(!form)return;renderCheckoutSummary();form.addEventListener('change',e=>{if(e.target.name==='shipping'){const delivery=e.target.value==='delivery';$('#address-fields').hidden=!delivery;$$('#address-fields input').forEach(el=>el.required=delivery);renderCheckoutSummary();}$('#checkout-feedback').innerHTML='';});form.addEventListener('input',()=>$('#checkout-feedback').innerHTML='');form.addEventListener('submit',async e=>{e.preventDefault();if(!cart.length){$('#checkout-feedback').textContent='הסל ריק. הוסיפי מוצרים לפני הכנת הבקשה.';return;}const d=Object.fromEntries(new FormData(form)),total=subtotal()+shippingAmount();if(d.payment==='card'&&PAY.cardEndpoint){const submit=form.querySelector('[type=submit]');submit.disabled=true;$('#checkout-feedback').innerHTML='<p class="notice">מעבירים אותך לדף התשלום המאובטח…</p>';try{const r=await fetch(PAY.cardEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({orderId:'LIAD-'+Date.now().toString(36).toUpperCase(),items:cart.map(l=>({id:l.id,qty:l.qty,price:products.find(p=>p.id===l.id).price})),shipping:shippingAmount(),total,customer:{name:d.name,phone:d.phone,email:d.email,city:d.city||'',street:d.street||'',delivery:d.shipping,notes:d.notes||''}})});const j=await r.json();if(!r.ok||!j.url)throw new Error();location.href=j.url;return;}catch{submit.disabled=false;$('#checkout-feedback').innerHTML='<p class="notice">לא הצלחנו לפתוח את דף התשלום. לא בוצע חיוב. אפשר לנסות שוב או לבחור בתיאום תשלום מול ליעד.</p>';return;}}const lines=cart.map(l=>{const p=products.find(p=>p.id===l.id);return `${p.title} | כמות ${l.qty} | ${money(p.price*l.qty)}`;}).join('\n');const body=`שלום ליעד, אשמח לתאם הזמנה:\n\n${lines}\n\nמשלוח: ${d.shipping==='pickup'?'איסוף עצמי מבנימינה':money(shippingAmount())}\nסך הכול לפי הקטלוג: ${money(total)}\n\nשם: ${d.name}\nטלפון: ${d.phone}\nאימייל: ${d.email}\n${d.shipping==='delivery'?`כתובת: ${d.street}, ${d.city}\n`:''}הערות: ${d.notes||'—'}\nאמצעי תשלום: ${d.payment==='bit'?'Bit':'תיאום מול ליעד'}\n\nאבקש לאשר זמינות, מחיר סופי ותיאום תשלום.`;const bit=d.payment==='bit'&&PAY.bitLink;$('#checkout-feedback').innerHTML=`${bit?`<div class="notice"><strong>תשלום ב־Bit: <bdi>${money(total)}</bdi></strong><p>פתחי את Bit ושלמי את הסכום המדויק. ההזמנה תאושר אחרי שליעד תראה את התשלום ותאשר מלאי. שלחי גם את בקשת ההזמנה במייל כדי שיהיו לה הפרטים.</p></div><a class="btn" href="${esc(PAY.bitLink)}" target="_blank" rel="noopener">לתשלום ב־Bit</a>`:''}<div class="notice"><strong>בקשת ההזמנה מוכנה.</strong><p>הבקשה עדיין לא נשלחה. פתחי אותה בתוכנת המייל ושלחי לליעד כדי לתאם את ההזמנה.</p></div>${btn('לפתיחת הבקשה במייל','mailto:'+MAIL+'?subject='+encodeURIComponent('בקשת הזמנה מ־LIAD')+'&body='+encodeURIComponent(body),'light')}<p class="form-help">אין תוכנת מייל? העתיקי את הבקשה ושלחי אל ${MAIL}.</p><button class="text-link" type="button" id="copy-order">להעתקת פרטי הבקשה</button><textarea id="order-text" class="field" rows="8" readonly aria-label="פרטי בקשת ההזמנה" hidden>${esc(body)}</textarea>`;$('#copy-order').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(body);toast('הבקשה הועתקה. אפשר להדביק אותה במייל.');}catch{$('#order-text').hidden=false;$('#order-text').select();toast('אפשר לסמן ולהעתיק את הבקשה.');}});$('#checkout-feedback').scrollIntoView({block:'center'});});}
function about(){return `${crumb('על ליעד')}<section class="section wrap"><div class="split"><div class="split-copy"><p class="eyebrow">THE WOMAN BEHIND LIAD</p><h1>נעים להכיר,<br><span class="script">אני ליעד.</span></h1><p class="lead" style="margin-top:28px">בעיניי, ציפורניים הן הרבה יותר מגימור יפה. הן דיוק, יצירתיות, ביטחון — והזדמנות לבנות משהו שהוא שלך.</p><p>עם 15 שנות ניסיון בתחום, הקמתי מקום שמחבר בין עבודה בסטודיו, לימוד מקצועי ויחס אישי. מקום שאפשר לשאול בו, להתנסות ולהתקדם.</p><div class="actions">${btn('להכיר את הקורסים','courses.html')}</div></div>${image('assets/img/opening/liad-real.webp','ליעד, מייסדת LIAD','class="split-photo about-photo"')}</div></section><section class="section tinted"><div class="wrap split">${image('assets/img/academy/studio.webp','הדרכה אישית בסטודיו','class="split-photo" loading="lazy"')}<div class="split-copy"><p class="eyebrow">SMALL GROUP. PERSONAL ATTENTION.</p><h2>לכל תלמידה,<br><span class="script">המקום שלה.</span></h2><p class="lead">עד שלוש תלמידות בכיתה. זמן לתרגל כל שלב. ליווי שנשאר גם אחרי סיום הקורס.</p><p>מהיסודות של הלק ג׳ל ועד בנייה באקריג׳ל ופדיקור קוסמטי — כל מסלול משלב תיאוריה, תרגול מעשי וערכת עבודה.</p><div class="actions">${btn('למצוא את המסלול שלך','courses.html','light')}</div></div></div></section>${contactBand()}`;}
function contact(){const topic=params.get('topic')||'';return `${crumb('יצירת קשר')}<div class="wrap">${heading('בואי <span class="script">נדבר.</span>','קורס חדש, מוצר לסטודיו או פשוט שאלה — אני כאן בשבילך.','LET’S TALK')}<div class="contact-layout"><div><p class="lead">השאירי את פרטי הפנייה, ונכין עבורך הודעה שאפשר לשלוח ישירות לליעד.</p><div class="actions"><a class="text-link" href="mailto:${MAIL}" dir="ltr">${MAIL}</a></div><div id="locations" class="small-section"><div class="location-card"><h3>בנימינה</h3><p>מתחם הפיל, בנימינה<br>איסוף עצמי ותיאום הגעה מול ליעד.</p><a class="text-link" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent('מתחם הפיל בנימינה')}" target="_blank" rel="noopener">לפתיחת המפה ↗</a></div><div class="location-card"><h3>נתניה</h3><p>שדרות בן צבי 18, נתניה<br>בתיאום מראש בלבד.</p><a class="text-link" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent('שדרות בן צבי 18 נתניה')}" target="_blank" rel="noopener">לפתיחת המפה ↗</a></div></div></div><form id="contact-form" class="form-panel"><h2>על מה תרצי לדבר?</h2><div class="form-grid"><label class="form-field">השם שלך<input type="text" name="name" autocomplete="name" required minlength="2"></label><label class="form-field">טלפון<input type="tel" name="phone" autocomplete="tel" pattern="[0-9+\\(\\)\\- ]{9,16}" required></label><label class="form-field full">אימייל<input type="email" name="email" autocomplete="email" required></label><label class="form-field full">נושא הפנייה<input type="text" name="topic" value="${esc(topic)}" required placeholder="קורס, מוצר או שאלה כללית"></label><label class="form-field full">מה תרצי לדעת?<textarea name="message" rows="4" required maxlength="2000"></textarea></label></div><p class="form-help">הטופס מכין הודעת מייל. הפנייה נשלחת רק כשתשלחי אותה מתוכנת המייל שלך.</p><button type="submit" class="btn">להכנת הפנייה${arrow}</button><div id="contact-feedback" class="form-feedback" aria-live="polite"></div></form></div></div>`;}
function wireContact(){const form=$('#contact-form');form.addEventListener('input',()=>$('#contact-feedback').innerHTML='');form.addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form)),body=`שלום ליעד,\n${d.message}\n\nשם: ${d.name}\nטלפון: ${d.phone}\nאימייל: ${d.email}`;$('#contact-feedback').innerHTML=`<p class="notice">הפנייה מוכנה. לחצי לפתיחת המייל ושלחי משם. הפנייה עדיין לא נשלחה.</p>${btn('לפתיחה במייל','mailto:'+MAIL+'?subject='+encodeURIComponent(d.topic)+'&body='+encodeURIComponent(body),'light')}`;});}
function journal(){return `${crumb('המגזין')}<div class="wrap">${heading('קצת ידע, <span class="script">הרבה השראה.</span>','טכניקות, כלים והרגלי עבודה — לקריאה בין לקוחה ללקוחה.','THE LIAD JOURNAL')}<div class="journal-grid section">${articles.map(journalCard).join('')}</div></div>${contactBand()}`;}
function article(){const i=Number(params.get('a')||0),a=articles[i];if(!a)return notFound('הכתבה לא נמצאה','index.html#journal','למגזין');document.title=a.title+' · LIAD';return `${crumb(a.title,'<a href="index.html#journal">המגזין</a><span aria-hidden="true">/</span>')}<div class="wrap"><section class="article-hero"><div><p class="eyebrow">${esc(a.cat)} · ${esc(a.time)}</p><h1>${esc(a.title)}</h1>${a.intro.map(p=>`<p>${p}</p>`).join('')}</div>${image(a.main,a.title)}</section><div class="article-layout"><aside><b>בכתבה הזאת</b>${a.secs.map(([h],k)=>`<a href="#section-${k}">${esc(h)}</a>`).join('')}<a href="index.html#journal">לכל הכתבות ←</a></aside><article class="article-body">${a.secs.map(([h,b],k)=>`<section id="section-${k}"><h2>${h}</h2>${b}</section>`).join('')}<div class="tip">${a.tip}</div><div class="sources"><strong>מקורות וקריאה נוספת</strong><ul>${a.src.map(k=>`<li><a href="${esc(window.ARTICLE_SOURCES[k][1])}" target="_blank" rel="noopener">${esc(window.ARTICLE_SOURCES[k][0])}</a></li>`).join('')}</ul></div><div class="actions">${btn('לשאלה מקצועית','index.html?topic='+encodeURIComponent(a.title)+'#contact','light')}</div></article></div><section class="section"><div class="section-head"><h2>עוד קצת <span class="script">השראה.</span></h2></div><div class="journal-grid">${articles.map((x,k)=>k===i?'':journalCard(x,k)).join('')}</div></section></div>`;}
const policyText={
'shipping.html':['משלוחים ואיסוף עצמי',`<h2>משלוח עד הבית</h2><p>לפי הגדרות הקטלוג שסופק, עלות המשלוח היא ${money(SHIPPING.flat)}. בקנייה מ־${money(SHIPPING.freeFrom)} המשלוח ללא עלות.</p><h2>איסוף עצמי</h2><p>ניתן לתאם איסוף ממתחם הפיל, בנימינה, ללא עלות. יש לתאם הגעה ולקבל אישור שהמוצרים מוכנים לאיסוף.</p><h2>מועד אספקה והחזרות</h2><p>זמן האספקה, זמינות המוצרים ותנאי ביטול או החזרה יאושרו מול ליעד לפני השלמת הזמנה ותשלום. לפנייה בנושא הזמנה אפשר לשלוח מייל אל <a href="mailto:${MAIL}">${MAIL}</a>.</p>`],
'privacy.html':['מידע על פרטיות',`<h2>מה נשמר באתר?</h2><p>סל הקניות והמועדפים נשמרים באחסון המקומי של הדפדפן במכשיר שלך. פרטי טפסי הפנייה וההזמנה נשארים בדף ואינם נשלחים לשרת על ידי הטופס.</p><h2>פנייה במייל</h2><p>לאחר הכנת בקשה, אפשר לפתוח הודעה בתוכנת המייל שלך. הפרטים מועברים לליעד רק כאשר את שולחת את ההודעה שם. ספק המייל שלך מטפל בהודעה לפי המדיניות שלו.</p><h2>שליטה במידע</h2><p>אפשר להסיר פריטים מהסל ומהמועדפים או למחוק את נתוני האתר בהגדרות הדפדפן. לפנייה בנוגע לפרטים שנשלחו לליעד, כתבי אל <a href="mailto:${MAIL}">${MAIL}</a>.</p><h2>שירותים חיצוניים</h2><p>קישורי המפה, המייל ומקורות הכתבות נפתחים בשירותים חיצוניים. בעת המעבר אליהם חלה מדיניות השירות הרלוונטי.</p>`],
 'terms.html':['מידע על הזמנות',`<h2>איך מזמינים?</h2><p>בוחרים מוצרים, מוסיפים לסל ומכינים בקשת הזמנה. הבקשה אינה נשלחת אוטומטית: יש לשלוח אותה מתוכנת המייל שלך אל ליעד.</p><h2>אישור ותשלום</h2><p>אין סליקה באתר ואין חיוב בהכנת הבקשה. ההזמנה דורשת אישור אישי של זמינות המלאי, המחיר הסופי ותנאי האספקה. את אופן התשלום מתאמים מול ליעד.</p><h2>המידע בקטלוג</h2><p>תיאורי המוצרים, המחירים ונתוני המלאי מוצגים לפי הקטלוג שסופק לאתר. הם אינם מלאי שמתעדכן בזמן אמת.</p><h2>הרשמה לקורס</h2><p>הסילבוסים מציגים את תוכנית הלימודים והמחיר שנמסרו על ידי האקדמיה. מועדים, מקום לימודים, תנאי תשלום וביטול יימסרו בתיאום ההרשמה.</p>`],
 'accessibility.html':['נגישות באתר',`<h2>גלישה נוחה וברורה</h2><p>האתר תוכנן לעבודה באמצעות מקלדת, עם קישור לדילוג לתוכן, סימון מיקוד, תוויות לטפסים, טקסט חלופי לתמונות והתאמה למסכים צרים. העדפה להפחתת תנועה נתמכת.</p><h2>סרטונים ותוכן מקורי</h2><p>סרטוני התלמידות והסילבוסים המקוריים מוצגים כפי שסופקו. לסילבוסים יש גם גרסת טקסט בדפי הקורסים. לחלק מהסרטונים אין כתוביות.</p><h2>נתקלת בקושי?</h2><p>אפשר לפנות לליעד במייל <a href="mailto:${MAIL}">${MAIL}</a> ולציין את העמוד ואת הבעיה. נשמח לסייע גם בקבלת מידע על מוצר או קורס בדרך חלופית.</p>`]
};
function policy(){const [title,body]=policyText[page];return `${crumb(title)}<article class="wrap policy">${heading(title,'','LIAD · INFORMATION')}${body}<div class="actions">${btn('ליצירת קשר','index.html#contact','light')}</div></article>`;}
function notFound(title='העמוד לא נמצא',href='index.html',label='לדף הבית'){return `<section class="section wrap">${empty(title,'נחזור למקום שבו אפשר למצוא בדיוק את מה שאת מחפשת.',href,label)}</section>`;}
mountShell();
if(originalHome){updateCart();return;}
const renders={'index.html':home,'courses.html':academy,'syllabus.html':syllabus,'shop.html':shop,'product.html':productPage,'checkout.html':checkout,'index.html#about':about,'index.html#contact':contact,'index.html#journal':journal,'article.html':article};
$('#main').innerHTML=policyText[page]?policy():(renders[page]||notFound)();
if(page==='shop.html'){wireShop();if(location.hash==='#catalog-search')$('#catalog-search').focus();}if(page==='product.html')wireProduct();if(page==='checkout.html')wireCheckout();if(page==='index.html#contact')wireContact();
if(page==='courses.html'){wireStories();wireCine();}
window.addEventListener('storage',e=>{if(e.key==='liad:cart'){const next=read('liad:cart',[]);cart=Array.isArray(next)?next.filter(l=>products.some(p=>p.id===l.id)&&Number.isInteger(l.qty)&&l.qty>0).map(l=>({id:l.id,qty:Math.min(l.qty,products.find(p=>p.id===l.id).stock)})).filter(l=>l.qty>0):[];$$('[data-cart-count]').forEach(el=>el.textContent=count());renderCart();if(page==='checkout.html'){renderCheckoutSummary();if($('#checkout-feedback'))$('#checkout-feedback').innerHTML='';}}});
})();
